package ai.xzkj.recruitment.resumes;
import ai.xzkj.recruitment.auth.SystemUser;import ai.xzkj.recruitment.candidates.CandidateJobContact;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.mock;
class ResumeIntakeTest{@Test void staysPendingUntilAnHrExplicitlyApprovesItForAi(){ResumeIntake intake=new ResumeIntake(mock(CandidateJobContact.class),ResumeIntakeSource.MANUAL,"a".repeat(64),"候选人已提供附件简历",Instant.parse("2026-08-30T06:00:00Z"));assertThat(intake.getStatus()).isEqualTo(ResumeIntakeStatus.PENDING_REVIEW);intake.review(ResumeIntakeStatus.APPROVED_FOR_AI,"已核对来源",mock(SystemUser.class),Instant.parse("2026-08-30T06:05:00Z"));assertThat(intake.getStatus()).isEqualTo(ResumeIntakeStatus.APPROVED_FOR_AI);assertThat(intake.getReviewNote()).isEqualTo("已核对来源");}}
